#include "speedbike_protocol.h"
uint8_t speedbikeCrc(const uint8_t *b,size_t n){uint16_t s=0;for(size_t i=0;i<n;++i)s+=b[i];return static_cast<uint8_t>(0x100-(s&0xff));}
size_t buildFrame(uint8_t o,uint8_t c,const uint8_t*p,uint8_t n,uint8_t*out,size_t cap){const size_t t=6+n;if(cap<t)return 0;out[0]=0x54;out[1]=0x46;out[2]=o;out[3]=c;out[4]=n;for(uint8_t i=0;i<n;++i)out[5+i]=p[i];out[5+n]=speedbikeCrc(out,5+n);return t;}
size_t buildSessionNotice(uint8_t*out,size_t cap){const uint8_t p[]={0x0a};return buildFrame(0x57,0x58,p,sizeof p,out,cap);} size_t buildPasswordFrame(uint8_t*out,size_t cap){const uint8_t p[]={0x0b,1,1,1,1,1,1};return buildFrame(0x57,0x58,p,sizeof p,out,cap);}
void FrameDecoder::discardFirst(){for(size_t i=1;i<size_;++i)bytes_[i-1]=bytes_[i];--size_;} void FrameDecoder::push(const uint8_t*b,size_t n){for(size_t i=0;i<n;++i){if(size_==sizeof bytes_)discardFirst();bytes_[size_++]=b[i];}}
bool FrameDecoder::next(DecodedFrame &o){while(size_>=2){if(bytes_[0]!=0x54||bytes_[1]!=0x46){discardFirst();continue;}if(size_<5)return false;const size_t t=6+bytes_[4];if(bytes_[4]>sizeof o.payload||size_<t){if(bytes_[4]>sizeof o.payload)discardFirst();return false;}if(speedbikeCrc(bytes_,t-1)!=bytes_[t-1]){discardFirst();continue;}o.op=bytes_[2];o.command=bytes_[3];o.length=bytes_[4];for(uint8_t i=0;i<o.length;++i)o.payload[i]=bytes_[5+i];for(size_t i=t;i<size_;++i)bytes_[i-t]=bytes_[i];size_-=t;return true;}return false;}
